package checkpoint

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
	"entire.io/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// TestReadCommitted_BackwardsCompatibility verifies that checkpoint metadata
// written with the old checkpoint.TokenUsage type can still be read with the
// new agent.TokenUsage type.
//
// This test simulates an existing checkpoint on the entire/sessions branch
// that was created before the refactoring that moved TokenUsage from the
// checkpoint package to the agent package.
func TestReadCommitted_BackwardsCompatibility(t *testing.T) {
	tempDir := t.TempDir()

	// Initialize a git repository with an initial commit
	repo, err := git.PlainInit(tempDir, false)
	if err != nil {
		t.Fatalf("failed to init git repo: %v", err)
	}

	// Create worktree and make initial commit on main branch
	worktree, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}

	readmeFile := filepath.Join(tempDir, "README.md")
	if err := os.WriteFile(readmeFile, []byte("# Test"), 0o644); err != nil {
		t.Fatalf("failed to write README: %v", err)
	}
	if _, err := worktree.Add("README.md"); err != nil {
		t.Fatalf("failed to add README: %v", err)
	}
	if _, err := worktree.Commit("Initial commit", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
	}); err != nil {
		t.Fatalf("failed to commit: %v", err)
	}

	// Simulate old metadata format by creating the metadata branch manually
	checkpointID := id.MustCheckpointID("abc123def456")
	sessionID := "test-session-old"

	// Create "old format" metadata JSON with token_usage structure
	// This simulates what was written before the refactoring
	oldMetadataJSON := map[string]interface{}{
		"checkpoint_id":  checkpointID.String(),
		"session_id":     sessionID,
		"strategy":       "manual-commit",
		"created_at":     "2024-01-15T10:00:00Z",
		"files_touched":  []string{"main.go", "test.go"},
		"agent":          "Claude Code", // Old agent type format
		"session_count":  1,
		"token_usage": map[string]interface{}{
			"input_tokens":          1000,
			"cache_creation_tokens": 200,
			"cache_read_tokens":     300,
			"output_tokens":         500,
			"api_call_count":        5,
			// Test nested subagent tokens as well
			"subagent_tokens": map[string]interface{}{
				"input_tokens":          100,
				"cache_creation_tokens": 20,
				"cache_read_tokens":     30,
				"output_tokens":         50,
				"api_call_count":        2,
			},
		},
	}

	metadataBytes, err := json.Marshal(oldMetadataJSON)
	if err != nil {
		t.Fatalf("failed to marshal old metadata: %v", err)
	}

	// Create the entire/sessions branch with the old metadata
	store := NewGitStore(repo)
	shardedPath := checkpointID.Path()

	// Build a tree with the old metadata structure
	metadataBlob, err := repo.Storer.SetEncodedObject(
		&plumbing.MemoryObject{},
	)
	if err != nil {
		t.Fatalf("failed to create metadata blob: %v", err)
	}
	writer, err := metadataBlob.Writer()
	if err != nil {
		t.Fatalf("failed to get blob writer: %v", err)
	}
	if _, err := writer.Write(metadataBytes); err != nil {
		t.Fatalf("failed to write metadata: %v", err)
	}
	writer.Close()

	// Create transcript blob
	transcriptBlob, err := repo.Storer.SetEncodedObject(
		&plumbing.MemoryObject{},
	)
	if err != nil {
		t.Fatalf("failed to create transcript blob: %v", err)
	}
	transcriptWriter, err := transcriptBlob.Writer()
	if err != nil {
		t.Fatalf("failed to get transcript writer: %v", err)
	}
	if _, err := transcriptWriter.Write([]byte("test transcript")); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}
	transcriptWriter.Close()

	// Build tree structure
	entries := map[string]object.TreeEntry{
		shardedPath + "/" + paths.MetadataFileName:  {Name: shardedPath + "/" + paths.MetadataFileName, Hash: metadataBlob.Hash(), Mode: 0o100644},
		shardedPath + "/" + paths.TranscriptFileName: {Name: shardedPath + "/" + paths.TranscriptFileName, Hash: transcriptBlob.Hash(), Mode: 0o100644},
	}

	treeHash, err := store.buildTree(entries)
	if err != nil {
		t.Fatalf("failed to build tree: %v", err)
	}

	// Create commit on entire/sessions branch
	commit := &object.Commit{
		Author:    object.Signature{Name: "Test", Email: "test@test.com"},
		Committer: object.Signature{Name: "Test", Email: "test@test.com"},
		Message:   "Checkpoint: " + checkpointID.String(),
		TreeHash:  treeHash,
	}
	commitObj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(commitObj); err != nil {
		t.Fatalf("failed to encode commit: %v", err)
	}
	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
	if err != nil {
		t.Fatalf("failed to store commit: %v", err)
	}

	// Create entire/sessions branch
	branchRef := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref := plumbing.NewHashReference(branchRef, commitHash)
	if err := repo.Storer.SetReference(ref); err != nil {
		t.Fatalf("failed to create metadata branch: %v", err)
	}

	// Now read the metadata using the new code
	result, err := store.ReadCommitted(context.Background(), checkpointID)
	if err != nil {
		t.Fatalf("ReadCommitted() error = %v", err)
	}

	// Verify the checkpoint info was correctly parsed
	if result.Info.CheckpointID != checkpointID {
		t.Errorf("CheckpointID = %v, want %v", result.Info.CheckpointID, checkpointID)
	}
	if result.Info.SessionID != sessionID {
		t.Errorf("SessionID = %q, want %q", result.Info.SessionID, sessionID)
	}
	if result.Info.Strategy != "manual-commit" {
		t.Errorf("Strategy = %q, want %q", result.Info.Strategy, "manual-commit")
	}
	if result.Info.Agent != agent.AgentTypeClaudeCode {
		t.Errorf("Agent = %q, want %q", result.Info.Agent, agent.AgentTypeClaudeCode)
	}

	// Verify token usage was correctly unmarshaled
	if result.Metadata.TokenUsage == nil {
		t.Fatal("TokenUsage should not be nil")
	}

	usage := result.Metadata.TokenUsage
	if usage.InputTokens != 1000 {
		t.Errorf("InputTokens = %d, want 1000", usage.InputTokens)
	}
	if usage.CacheCreationTokens != 200 {
		t.Errorf("CacheCreationTokens = %d, want 200", usage.CacheCreationTokens)
	}
	if usage.CacheReadTokens != 300 {
		t.Errorf("CacheReadTokens = %d, want 300", usage.CacheReadTokens)
	}
	if usage.OutputTokens != 500 {
		t.Errorf("OutputTokens = %d, want 500", usage.OutputTokens)
	}
	if usage.APICallCount != 5 {
		t.Errorf("APICallCount = %d, want 5", usage.APICallCount)
	}

	// Verify nested subagent token usage
	if usage.SubagentTokens == nil {
		t.Fatal("SubagentTokens should not be nil")
	}
	subUsage := usage.SubagentTokens
	if subUsage.InputTokens != 100 {
		t.Errorf("SubagentTokens.InputTokens = %d, want 100", subUsage.InputTokens)
	}
	if subUsage.CacheCreationTokens != 20 {
		t.Errorf("SubagentTokens.CacheCreationTokens = %d, want 20", subUsage.CacheCreationTokens)
	}
	if subUsage.CacheReadTokens != 30 {
		t.Errorf("SubagentTokens.CacheReadTokens = %d, want 30", subUsage.CacheReadTokens)
	}
	if subUsage.OutputTokens != 50 {
		t.Errorf("SubagentTokens.OutputTokens = %d, want 50", subUsage.OutputTokens)
	}
	if subUsage.APICallCount != 2 {
		t.Errorf("SubagentTokens.APICallCount = %d, want 2", subUsage.APICallCount)
	}

	// Verify transcript content
	if string(result.Transcript) != "test transcript" {
		t.Errorf("Transcript = %q, want %q", string(result.Transcript), "test transcript")
	}
}

