	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// TestTokenUsage_BackwardsCompatibility verifies that the TokenUsage type
// change from checkpoint.TokenUsage to agent.TokenUsage doesn't break
// JSON marshaling/unmarshaling.
//
// This test ensures that:
// 1. Token usage data can be written with the new agent.TokenUsage type
// 2. It can be read back correctly
// 3. The JSON structure is identical (same field names)
// 4. Nested subagent tokens work correctly
//
// Background: TokenUsage was moved from the checkpoint package to the agent
// package. While the struct definition is identical, this test verifies that
// existing checkpoint metadata can still be read without issues.
func TestTokenUsage_BackwardsCompatibility(t *testing.T) {
	tempDir := t.TempDir()

	// Initialize a git repository with an initial commit
	repo, err := git.PlainInit(tempDir, false)
	if err != nil {
		t.Fatalf("failed to init git repo: %v", err)
	}

	// Create worktree and make initial commit
	worktree, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}

	readmeFile := filepath.Join(tempDir, "README.md")
	if err := os.WriteFile(readmeFile, []byte("# Test"), 0o644); err != nil {
		t.Fatalf("failed to write README: %v", err)
	}
	if _, err := worktree.Add("README.md"); err != nil {
		t.Fatalf("failed to add README: %v", err)
	}
	if _, err := worktree.Commit("Initial commit", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
	}); err != nil {
		t.Fatalf("failed to commit: %v", err)
	}

	// Create checkpoint store
	store := NewGitStore(repo)

	// Test data with comprehensive token usage including nested subagent tokens
	checkpointID := id.MustCheckpointID("abc123def456")
	sessionID := "test-session-tokens"
	agentType := agent.AgentTypeClaudeCode

	tokenUsage := &agent.TokenUsage{
		InputTokens:         1000,
		CacheCreationTokens: 200,
		CacheReadTokens:     300,
		OutputTokens:        500,
		APICallCount:        5,
		SubagentTokens: &agent.TokenUsage{
			InputTokens:         100,
			CacheCreationTokens: 20,
			CacheReadTokens:     30,
			OutputTokens:        50,
			APICallCount:        2,
		},
	}

	// Write checkpoint with token usage
	err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
		CheckpointID: checkpointID,
		SessionID:    sessionID,
		Strategy:     "manual-commit",
		Agent:        agentType,
		Transcript:   []byte("test transcript content"),
		AuthorName:   "Test Author",
		AuthorEmail:  "test@example.com",
		TokenUsage:   tokenUsage,
	})
	if err != nil {
		t.Fatalf("WriteCommitted() error = %v", err)
	}

	// Read it back
	result, err := store.ReadCommitted(context.Background(), checkpointID)
	if err != nil {
		t.Fatalf("ReadCommitted() error = %v", err)
	}

	// Verify metadata fields
	if result.Metadata.CheckpointID != checkpointID {
		t.Errorf("CheckpointID = %v, want %v", result.Metadata.CheckpointID, checkpointID)
	}
	if result.Metadata.SessionID != sessionID {
		t.Errorf("SessionID = %q, want %q", result.Metadata.SessionID, sessionID)
	}
	if result.Metadata.Agent != agentType {
		t.Errorf("Agent = %q, want %q", result.Metadata.Agent, agentType)
	}

	// Verify token usage was correctly round-tripped
	if result.Metadata.TokenUsage == nil {
		t.Fatal("TokenUsage should not be nil")
	}

	usage := result.Metadata.TokenUsage
	if usage.InputTokens != 1000 {
		t.Errorf("InputTokens = %d, want 1000", usage.InputTokens)
	}
	if usage.CacheCreationTokens != 200 {
		t.Errorf("CacheCreationTokens = %d, want 200", usage.CacheCreationTokens)
	}
	if usage.CacheReadTokens != 300 {
		t.Errorf("CacheReadTokens = %d, want 300", usage.CacheReadTokens)
	}
	if usage.OutputTokens != 500 {
		t.Errorf("OutputTokens = %d, want 500", usage.OutputTokens)
	}
	if usage.APICallCount != 5 {
		t.Errorf("APICallCount = %d, want 5", usage.APICallCount)
	}

	// Verify nested subagent token usage
	if usage.SubagentTokens == nil {
		t.Fatal("SubagentTokens should not be nil")
	}
	subUsage := usage.SubagentTokens
	if subUsage.InputTokens != 100 {
		t.Errorf("SubagentTokens.InputTokens = %d, want 100", subUsage.InputTokens)
	}
	if subUsage.CacheCreationTokens != 20 {
		t.Errorf("SubagentTokens.CacheCreationTokens = %d, want 20", subUsage.CacheCreationTokens)
	}
	if subUsage.CacheReadTokens != 30 {
		t.Errorf("SubagentTokens.CacheReadTokens = %d, want 30", subUsage.CacheReadTokens)
	}
	if subUsage.OutputTokens != 50 {
		t.Errorf("SubagentTokens.OutputTokens = %d, want 50", subUsage.OutputTokens)
	}
	if subUsage.APICallCount != 2 {
		t.Errorf("SubagentTokens.APICallCount = %d, want 2", subUsage.APICallCount)
	}

	// Verify transcript content
	if string(result.Transcript) != "test transcript content" {
		t.Errorf("Transcript = %q, want %q", string(result.Transcript), "test transcript content")
	}
}

// TestTokenUsage_JSONStructure verifies that agent.TokenUsage has the exact
// same JSON structure as the old checkpoint.TokenUsage to ensure compatibility
// with existing checkpoint metadata files.
func TestTokenUsage_JSONStructure(t *testing.T) {
	// Create a token usage struct with all fields populated
	usage := &agent.TokenUsage{
		InputTokens:         1000,
		CacheCreationTokens: 200,
		CacheReadTokens:     300,
		OutputTokens:        500,
		APICallCount:        5,
		SubagentTokens: &agent.TokenUsage{
			InputTokens:  100,
			OutputTokens: 50,
			APICallCount: 2,
		},
	}

	// Marshal to JSON
	jsonBytes, err := json.Marshal(usage)
	if err != nil {
		t.Fatalf("failed to marshal TokenUsage: %v", err)
	}

	// Verify JSON structure has expected field names (these are what existing
	// checkpoint metadata files use)
	jsonStr := string(jsonBytes)
	requiredFields := []string{
		`"input_tokens"`,
		`"cache_creation_tokens"`,
		`"cache_read_tokens"`,
		`"output_tokens"`,
		`"api_call_count"`,
		`"subagent_tokens"`,
	}

	for _, field := range requiredFields {
		if jsonStr == "" || len(jsonStr) == 0 {
			t.Fatalf("JSON is empty")
		}
		// Check if field exists in JSON string
		found := false
		for i := 0; i < len(jsonStr)-len(field)+1; i++ {
			if i+len(field) <= len(jsonStr) && jsonStr[i:i+len(field)] == field {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("JSON should contain field %s, got: %s", field, jsonStr)
		}
	}

	// Unmarshal back to verify round-trip
	var decoded agent.TokenUsage
	if err := json.Unmarshal(jsonBytes, &decoded); err != nil {
		t.Fatalf("failed to unmarshal TokenUsage: %v", err)
	}

	// Verify all fields match
	if decoded.InputTokens != usage.InputTokens {
		t.Errorf("InputTokens mismatch after round-trip: got %d, want %d", decoded.InputTokens, usage.InputTokens)
	}
	if decoded.CacheCreationTokens != usage.CacheCreationTokens {
		t.Errorf("CacheCreationTokens mismatch after round-trip: got %d, want %d", decoded.CacheCreationTokens, usage.CacheCreationTokens)
	}
	if decoded.CacheReadTokens != usage.CacheReadTokens {
		t.Errorf("CacheReadTokens mismatch after round-trip: got %d, want %d", decoded.CacheReadTokens, usage.CacheReadTokens)
	}
	if decoded.OutputTokens != usage.OutputTokens {
		t.Errorf("OutputTokens mismatch after round-trip: got %d, want %d", decoded.OutputTokens, usage.OutputTokens)
	}
	if decoded.APICallCount != usage.APICallCount {
		t.Errorf("APICallCount mismatch after round-trip: got %d, want %d", decoded.APICallCount, usage.APICallCount)
	}
	if decoded.SubagentTokens == nil {
		t.Fatal("SubagentTokens should not be nil after round-trip")
	}
	if decoded.SubagentTokens.InputTokens != usage.SubagentTokens.InputTokens {
		t.Errorf("SubagentTokens.InputTokens mismatch: got %d, want %d", decoded.SubagentTokens.InputTokens, usage.SubagentTokens.InputTokens)
	}
}

